public class SlugBinder : IModelBinder
{
    public Task BindModelAsync(ModelBindingContext ctx)
    {
        var v = ctx.ValueProvider.GetValue(ctx.ModelName).FirstValue;
        ctx.Result = ModelBindingResult.Success(v?.ToLowerInvariant());
        return Task.CompletedTask;
    }
}

